<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Order extends Model { protected $fillable=['order_number','customer_id','status','subtotal','total']; protected $casts=['subtotal'=>'decimal:2','total'=>'decimal:2']; public function customer(){return $this->belongsTo(Customer::class);} public function items(){return $this->hasMany(OrderItem::class);} }
